void delete_comment(struct SPECS *S, char *start) { /* <=== delete_comment */ 
    struct COMMENT *p, *q;

    q = NULL;
    for (p = S->comments; p != NULL ; p = p->next) {
        if (!strcmp(p->start, start)) {
            if (q == NULL )
                S->comments = p->next;
            else
                q->next = p->next;
            free(p->start);
            free(p->end);
            free(p);
            free(start);
            return;
        } else
            q = p;
    }
    free(start);
}

char *strNl2(char *s, int check_delim) { /* <=== strNl2 */ 
    char *u;
    int neg;
    u = s;
    if (check_delim && !isDelim(*s))
        bug("character not allowed to start a syntax specifier");
    while (*s != '"') {
        if (((*s & 0x60) == 0) && (*s != '\n') && (*s != '\t'))
            bug("character not allowed in syntax specifier");
        if (*s == '\\') {
            neg = (s[1] == '!');
            switch (s[neg + 1]) {
            case 'n':
            case 'r':
                *u = '\n';
                break;
            case 't':
                *u = '\t';
                break;
            case 'b': /* one or more spaces */
                *u = '\001';
                break;
            case 'w': /* zero or more spaces */
                if (neg)
                    bug("\\w and \\W cannot be negated");
                *u = '\002';
                break;
            case 'B': /* one or more spaces or \n */
                *u = '\003';
                break;
            case 'W': /* zero or more spaces or \n */
                if (neg)
                    bug("\\w and \\W cannot be negated");
                *u = '\004';
                break;
            case 'a': /* alphabetic */
                *u = '\005';
                break;
            case 'A': /* alphabetic + space */
                *u = '\006';
                break;
            case '#': /* numeric */
                *u = '\007';
                break;
            case 'i': /* identifier */
                *u = '\010';
                break;
            case 'o': /* operator */
                *u = '\013';
                break;
            case 'O': /* operator/parenthesis */
                *u = '\014';
                break;
            case '"':
            case '\\':
                if (!neg) {
                    *u = s[1];
                    break;
                }
            default:
                bug("unknown escape sequence in syntax specifier");
            }
            if (neg > 0)
                *u += (char) 128;
            s += neg + 1;
        } else if (*s == ' ')
            *u = '\001';
        else
            *u = *s;
        if (*s == 0)
            bug("unterminated string in #mode command");
        s++;
        u++;
    }
    *u = 0;
    return (s + 1);
}

void write_include_marker(FILE *f, int lineno, char *filename, /* <=== write_include_marker */ 
        const char *marker) {
