int IsInCharset(CHARSET_SUBSET x, int c) { /* <=== IsInCharset */ 
    return (x[c >> LOG_LONG_BITS] & 1L << (c & ((1 << LOG_LONG_BITS) - 1))) != 0;
}

char *remove_comments(int start, int end, int cmtmode) { /* <=== remove_comments */ 
    char *s, *t;

    t = s = malloc(end - start + 1);
    while (start < end) {
        SkipPossibleComments(&start, cmtmode, 1);
        if (start < end) {
            *t = getChar(start++);
            if ((*t == S->User.quotechar) && (start < end)) {
                *(++t) = getChar(start++);
            }
            t++;
        }
    }
    *t = 0;
    return s;
}

int isWhitesep(const char *s) { /* <=== isWhitesep */ 
    while (isWhite(*s) || (*s == '\001') || (*s == '\002') || (*s == '\003')
            || (*s == '\004'))
        s++;
    return (*s == 0);
}

int nowhite_strcmp(char *s, char *t) { /* <=== nowhite_strcmp */ 
    char *p;

    while (isWhite(*s))
        s++;
    while (isWhite(*t))
        t++;
    if ((*s == 0) || (*t == 0))
        return strcmp(s, t);
    p = s + strlen(s) - 1;
    while (isWhite(*p))
        *(p--) = 0;
    p = t + strlen(t) - 1;
    while (isWhite(*p))
        *(p--) = 0;
    return strcmp(s, t);
}

